package com.campusiq.platform.strategy;
import com.campusiq.platform.client.GeeksForGeeksClient; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class GeeksForGeeksStrategyTest { @Test void mapsOptionalGfgStatistics(){var c=mock(GeeksForGeeksClient.class); when(c.basic("ada")).thenReturn(new GeeksForGeeksClient.BasicResponse("success","ada",new GeeksForGeeksClient.BasicData(120,120,1500d,1600d,900L))); when(c.profile("ada")).thenReturn(new GeeksForGeeksClient.ProfileResponse("success","ada",new GeeksForGeeksClient.ProfileData("Ada","ada","avatar",null,null,900L,null,4,12))); when(c.stats("ada")).thenReturn(new GeeksForGeeksClient.StatsResponse("success","ada",new GeeksForGeeksClient.StatsData(120,1000,60d,new GeeksForGeeksClient.Difficulty(30,60,30)))); when(c.heatmap("ada")).thenReturn(new GeeksForGeeksClient.HeatmapResponse("success","ada",new GeeksForGeeksClient.HeatmapData(4,12,20))); var p=new GeeksForGeeksStrategy(c).fetchProfile("ada"); assertThat(p.totalSolved()).isEqualTo(120); assertThat(p.easySolved()).isEqualTo(30); assertThat(p.codingScore()).isEqualTo(900L); assertThat(p.currentStreak()).isEqualTo(4); assertThat(p.maxRating()).isEqualTo(1600d); } @Test void rejectsUnsuccessfulBasicResponse(){var c=mock(GeeksForGeeksClient.class);when(c.basic("missing")).thenReturn(new GeeksForGeeksClient.BasicResponse("error","missing",null));assertThat(new GeeksForGeeksStrategy(c).verifyUser("missing")).isFalse();}}
